package de.mika.promptwerk;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @LooperMode(LooperMode.Mode.PAUSED)
public class DriveMergeTests {
 final String owner="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
 JSONObject entry(String id,String text)throws Exception{return new JSONObject().put("id",id).put("title","Auftrag").put("text",text).put("type","prompt").put("project","").put("star",false).put("archived",false).put("files",new JSONArray()).put("cloud",true).put("cloudOwner",owner);}
 JSONObject row(JSONObject e,int base)throws Exception{return new JSONObject().put("entry",e).put("base",base).put("dirty",true).put("deleted",false).put("seenLocal",true);}
 JSONObject result(String id,int version,JSONObject remote)throws Exception{return new JSONObject().put("id",id).put("committedVersion",version).put("conflict",false).put("deleteConflict",false).put("document",new JSONObject().put("entries",remote==null?new JSONObject():new JSONObject().put(id,remote)).put("deleted",new JSONObject()).put("files",new JSONObject()));}
 @Test public void flightPersistsOriginalPayloadAndOperationAcrossNewEdit()throws Exception{JSONObject r=row(entry("one","A"),1);JSONObject f=DriveMerge.copy(DriveMerge.startFlight(r));r.put("entry",entry("one","B"));JSONObject retry=DriveMerge.startFlight(r);assertEquals(f.getString("operation"),retry.getString("operation"));assertEquals("A",retry.getJSONObject("entry").getString("text"));}
 @Test public void acknowledgingOldFlightKeepsNewEditAndAdvancesOnlyAcknowledgedBase()throws Exception{JSONObject r=row(entry("one","A"),1);DriveMerge.startFlight(r);r.put("entry",entry("one","B"));JSONObject rows=new JSONObject().put("one",r);DriveMerge.acknowledge(rows,"one",result("one",2,entry("one","A").put("syncVersion",4)),owner);assertTrue(r.getBoolean("dirty"));assertFalse(r.has("flight"));assertEquals(2,r.getInt("base"));assertEquals("B",r.getJSONObject("entry").getString("text"));}
 @Test public void deleteConflictRestoresRemoteEntryAndDoesNotBlockNextRow()throws Exception{JSONObject r=row(entry("one","Offline"),1).put("deleted",true);DriveMerge.startFlight(r);JSONObject second=row(entry("two","Folgeeintrag"),0),rows=new JSONObject().put("one",r).put("two",second);JSONObject remote=entry("one","Neu auf Gerät B").put("syncVersion",2);JSONObject answer=result("one",2,remote).put("deleteConflict",true);String notice=DriveMerge.acknowledge(rows,"one",answer,owner);assertTrue(notice.contains("neuere Fassung"));assertFalse(rows.getJSONObject("one").getBoolean("deleted"));assertFalse(rows.getJSONObject("one").getBoolean("dirty"));assertFalse(rows.getJSONObject("one").has("flight"));assertEquals("Neu auf Gerät B",rows.getJSONObject("one").getJSONObject("entry").getString("text"));assertTrue(rows.getJSONObject("two").getBoolean("dirty"));}
 @Test public void successfulDeleteAcknowledgementRemovesQueueRecord()throws Exception{JSONObject r=row(entry("one","A"),1).put("deleted",true);DriveMerge.startFlight(r);JSONObject records=new JSONObject().put("one",r);DriveMerge.acknowledge(records,"one",result("one",2,null),owner);assertFalse(records.has("one"));}
 @Test public void editWhileDeleteInFlightSurvivesAcknowledgement()throws Exception{JSONObject r=row(entry("one","A"),1).put("deleted",true);DriveMerge.startFlight(r);r.put("entry",entry("one","Neue Änderung")).put("deleted",false);JSONObject records=new JSONObject().put("one",r);DriveMerge.acknowledge(records,"one",result("one",2,null),owner);assertTrue(records.getJSONObject("one").getBoolean("dirty"));assertEquals("Neue Änderung",records.getJSONObject("one").getJSONObject("entry").getString("text"));}
 @Test public void conflictReplyMissingCurrentEntryStillPreservesAssignedCopy()throws Exception{JSONObject r=row(entry("one","Offline"),1);DriveMerge.startFlight(r);JSONObject records=new JSONObject().put("one",r);DriveMerge.acknowledge(records,"one",result("conflict-copy",2,null).put("conflict",true),owner);assertFalse(records.has("one"));assertEquals("Offline",records.getJSONObject("conflict-copy").getJSONObject("entry").getString("text"));assertEquals(2,records.getJSONObject("conflict-copy").getInt("base"));}
 @Test public void accountMismatchNeverQueuesAnotherAccountsEntry()throws Exception{JSONObject records=new JSONObject();JSONObject other=entry("private","Text").put("cloudOwner","bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");DriveMerge.capture(records,new JSONArray().put(other),owner);assertEquals(0,records.length());}
 @Test public void localOnlyChoiceKeepsRemoteCopyOutOfDeletionQueue()throws Exception{JSONObject r=row(entry("one","A"),1).put("dirty",false);JSONObject records=new JSONObject().put("one",r);DriveMerge.capture(records,new JSONArray().put(entry("one","lokal").put("cloud",false)),owner);assertTrue(r.getBoolean("excluded"));assertFalse(r.optBoolean("deleted"));DriveMerge.capture(records,new JSONArray(),owner);assertFalse(r.optBoolean("deleted"));}
 @Test public void pulledEntryNotYetShownLocallyIsNotMistakenForDeletion()throws Exception{JSONObject records=new JSONObject(),remote=entry("new","Web").put("syncVersion",5);DriveMerge.pull(records,new JSONObject().put("entries",new JSONObject().put("new",remote)).put("deleted",new JSONObject()),owner);DriveMerge.capture(records,new JSONArray(),owner);assertFalse(records.getJSONObject("new").optBoolean("deleted"));assertFalse(records.getJSONObject("new").optBoolean("dirty"));}
 @Test public void canonicalContentIgnoresWireMetadataOrderingAndClock()throws Exception{JSONObject a=entry("one","Text"),b=new JSONObject(a.toString());b.put("updatedAt",999).put("syncVersion",7);assertEquals(DriveMerge.content(a),DriveMerge.content(b));}
 @Test public void completeCollectionPreservesAllFieldsAndIncludesAttachments()throws Exception{
  JSONObject local=entry("local","Text").put("cloud",false).put("archived",true).put("star",true).put("project","Projekt").put("files",new JSONArray().put(new JSONObject().put("key","f").put("sync",false)));
  JSONObject complete=DriveMerge.completeCollection(new JSONArray().put(local),owner).getJSONObject(0);
  assertTrue(complete.getBoolean("cloud"));assertEquals(owner,complete.getString("cloudOwner"));assertTrue(complete.getBoolean("archived"));assertTrue(complete.getBoolean("star"));assertEquals("Projekt",complete.getString("project"));assertEquals("Text",complete.getString("text"));assertTrue(complete.getJSONArray("files").getJSONObject(0).getBoolean("sync"));assertFalse(local.getBoolean("cloud"));assertFalse(local.getJSONArray("files").getJSONObject(0).getBoolean("sync"));
 }
 @Test public void completeCollectionDoesNotReassignAnotherGoogleAccount()throws Exception{
  JSONObject foreign=entry("foreign","Privat").put("cloudOwner","bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");
  assertEquals(DriveMerge.canonical(foreign),DriveMerge.canonical(DriveMerge.completeCollection(new JSONArray().put(foreign),owner).getJSONObject(0)));
 }
}
